import{_ as a,o as t,c as i,a2 as r}from"./chunks/framework.CyZTVJbV.js";const m=JSON.parse('{"title":"kiwa v1.34 released — Frontend 深化 (@kiwa-lab/component v0.3.0 + @kiwa-lab/nextjs v1.2.0 + 8 axis advanced frontend + 縦深化 pair 第 6 pair 連続化)","description":"","frontmatter":{},"headers":[],"relativePath":"announcements/v1.34/zenn-article.md","filePath":"announcements/v1.34/zenn-article.md"}'),n={name:"announcements/v1.34/zenn-article.md"};function o(s,e,d,l,c,p){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="kiwa-v1-34-released-—-frontend-深化-kiwa-lab-component-v0-3-0-kiwa-lab-nextjs-v1-2-0-8-axis-advanced-frontend-縦深化-pair-第-6-pair-連続化" tabindex="-1">kiwa v1.34 released — Frontend 深化 (@kiwa-lab/component v0.3.0 + @kiwa-lab/nextjs v1.2.0 + 8 axis advanced frontend + 縦深化 pair 第 6 pair 連続化) <a class="header-anchor" href="#kiwa-v1-34-released-—-frontend-深化-kiwa-lab-component-v0-3-0-kiwa-lab-nextjs-v1-2-0-8-axis-advanced-frontend-縦深化-pair-第-6-pair-連続化" aria-label="Permalink to &quot;kiwa v1.34 released — Frontend 深化 (@kiwa-lab/component v0.3.0 + @kiwa-lab/nextjs v1.2.0 + 8 axis advanced frontend + 縦深化 pair 第 6 pair 連続化)&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li><strong>kiwa v1.34 released</strong> — Frontend 深化 milestone (advanced frontend semantics 8 axis + real driver + 縦深化 pair 第 6 pair 連続化)</li><li><strong><code>@kiwa-lab/component</code> v0.2.0 → v0.3.0 + <code>@kiwa-lab/nextjs</code> v1.1.0 → v1.2.0 pair minor bump</strong> — 8 axis advanced frontend semantics + real driver env-gate + 3 target × 8 axis neutral state machine 追加</li><li><strong>8 axis semantics</strong> = rsc-harness + streaming-ssr + view-transitions + form-action-advanced + server-action-advanced + partial-prerendering + interception-routes + parallel-routes-advanced</li><li><strong>3 dogfood app 新規</strong> — nextjs-rsc-streaming-app v2 + nextjs-server-action-app 新規 + storybook-8-mdx-app 新規、 全 7 軸 release gate PASS + real driver env-gate</li><li><strong>縦深化 pair pattern 第 6 pair 連続化</strong> — Auth pair (v1.21→v1.22) + Realtime pair (v1.13→v1.28) + Streaming pair (v1.20→v1.31) + Database pair (v1.14→v1.32) + Payment pair (v1.23→v1.33) + <strong>Frontend pair (v1.16→v1.34)</strong>、 縦深化戦略 SSOT を frontend production layer に拡張</li><li><strong>12 milestone 連続 snippet validation streak</strong> (v1.23-v1.34)</li><li><strong>kiwa runtime fixture 35 packages 維持</strong> (component + nextjs 既存 package の pair minor 拡張)</li><li>v1.11 以降 24 milestone 連続完遂</li></ul><h2 id="v1-34-が解決したい問題-—-frontend-production-semantics-の-testing-gap" tabindex="-1">v1.34 が解決したい問題 — Frontend production semantics の testing gap <a class="header-anchor" href="#v1-34-が解決したい問題-—-frontend-production-semantics-の-testing-gap" aria-label="Permalink to &quot;v1.34 が解決したい問題 — Frontend production semantics の testing gap&quot;">​</a></h2><p>v1.16 で <code>@kiwa-lab/component</code> v0.1 (Storybook 8 + Playwright Component Testing + Chromatic の 3 target を単一 API surface で unify する mock harness) を land、 v1.2 で <code>@kiwa-lab/nextjs</code> v1.0 (Next.js App Router / Pages Router / Edge Runtime の unified adapter) を land した時点で、 kiwa は 3 target 上に単一の component + nextjs test envelope を統一 mock として提供していた。 browser 経由の live rendering 不要で mock only mode で走る、 実 test 環境の inner-loop 速度を確保する目的の layer。</p><p>しかし v1.16 / v1.2 land 後の実行観測で判明したのは、 real production frontend setup (React 19 + Next.js 15 App Router + Server Components + Server Actions + view transitions) で頻繁に遭遇する <strong>8 axis の advanced frontend semantics</strong> — RSC で Suspense fallback が resolved chunk に置換されない sequencing bug / selective hydration が 4 boundary のうち 1 つだけ pending の状態で stuck / view transition の element transition promise を await 忘れて timing off / useOptimistic で optimistic patch が resolved shape 不一致で stuck / Server Action の revalidateTag typo で wrong path revalidate / Partial Prerendering で static shell の Suspense boundary が外れて dynamic hole flush 失敗 / (.)intercept が親 segment を swallowing / parallel route で default.tsx なしで loading slot 出ない — が v1.16 の 6 base semantics + v1.2 の 5 base semantics だけでは cover できないこと。</p><p>v1.34 はこの gap を埋める深化 milestone。 8 axis advanced frontend semantics + real driver env-gate + 3 dogfood app 新規 で <strong>production frontend testing SSOT</strong> を確立、 kiwa の縦深化 pair pattern (basic mock → advanced real driver) を 6 pair 目として frontend production layer に拡張。</p><h2 id="v1-34-で追加した-8-axis-advanced-frontend-semantics" tabindex="-1">v1.34 で追加した 8 axis advanced frontend semantics <a class="header-anchor" href="#v1-34-で追加した-8-axis-advanced-frontend-semantics" aria-label="Permalink to &quot;v1.34 で追加した 8 axis advanced frontend semantics&quot;">​</a></h2><h3 id="_1-rsc-harness-rsc-harness-ts" tabindex="-1">1. RSC harness (<code>rsc-harness.ts</code>) <a class="header-anchor" href="#_1-rsc-harness-rsc-harness-ts" aria-label="Permalink to &quot;1. RSC harness (`rsc-harness.ts`)&quot;">​</a></h3><p>React Server Component render + Suspense boundary tracking (nested boundary の enter / exit 対応) + streaming HTML chunk assertion (chunk 単位の emission event) + chunk order guard (server が emit した chunk order が client hydration order と一致) の 4 axis を pure state machine として実装。 <code>startRscHarness</code> → <code>beginRscRender</code> → <code>enterSuspenseBoundary</code> → <code>streamHtmlChunk</code> → <code>completeRscRender</code> | <code>failRscRender</code> の 5 event envelope。 real driver env-gate で Next.js 15 App Router の実 RSC render に routing。</p><h3 id="_2-streaming-ssr-streaming-ssr-ts" tabindex="-1">2. Streaming SSR (<code>streaming-ssr.ts</code>) <a class="header-anchor" href="#_2-streaming-ssr-streaming-ssr-ts" aria-label="Permalink to &quot;2. Streaming SSR (`streaming-ssr.ts`)&quot;">​</a></h3><p>Suspense pending state 追跡 + selective hydration (per-boundary hydration order) + progressive hydration state machine (client-side event-driven hydration prioritization) + error boundary correlation (error boundary が捕捉した error を pending suspense と紐付ける) の 4 axis 統一実装。 <code>markSuspensePending</code> → <code>captureErrorBoundary</code> → <code>startProgressiveHydration</code> → <code>completeSelectiveHydration</code> の 4-event envelope。</p><h3 id="_3-view-transitions-view-transitions-ts" tabindex="-1">3. View transitions (<code>view-transitions.ts</code>) <a class="header-anchor" href="#_3-view-transitions-view-transitions-ts" aria-label="Permalink to &quot;3. View transitions (`view-transitions.ts`)&quot;">​</a></h3><p>element transition (個別要素の CSS view-transition-name 追跡) + document transition (全 document 遷移の startViewTransition() promise 追跡) + animation promise tracking (finished / ready promise の await 状態 assertion) + assertion timing (transition の各 phase で assertion 可能な時点を明示) の 4 axis 統一実装。</p><h3 id="_4-form-action-advanced-form-action-advanced-ts" tabindex="-1">4. Form action advanced (<code>form-action-advanced.ts</code>) <a class="header-anchor" href="#_4-form-action-advanced-form-action-advanced-ts" aria-label="Permalink to &quot;4. Form action advanced (`form-action-advanced.ts`)&quot;">​</a></h3><p>useFormStatus pending state (form 送信中の pending / data / method / action 追跡) + useOptimistic patch ledger (optimistic update と resolved update の diff 追跡) + progressive enhancement (JS off state での form action 動作保証) + resolved-vs-optimistic diff (optimistic patch が resolved value と不一致な時の detection) の 4 axis 統一実装。</p><h3 id="_5-server-action-advanced-server-action-advanced-ts" tabindex="-1">5. Server action advanced (<code>server-action-advanced.ts</code>) <a class="header-anchor" href="#_5-server-action-advanced-server-action-advanced-ts" aria-label="Permalink to &quot;5. Server action advanced (`server-action-advanced.ts`)&quot;">​</a></h3><p>form action submit (Server Action への form 送信 event 発火) + revalidatePath prefix guard (typo で他 path を revalidate してしまわないための prefix check) + revalidateTag string match (tag の完全一致 assertion) + redirect action (Server Action からの redirect() 呼出) の 4 axis 統一実装。</p><h3 id="_6-partial-prerendering-partial-prerendering-ts" tabindex="-1">6. Partial prerendering (<code>partial-prerendering.ts</code>) <a class="header-anchor" href="#_6-partial-prerendering-partial-prerendering-ts" aria-label="Permalink to &quot;6. Partial prerendering (`partial-prerendering.ts`)&quot;">​</a></h3><p>static shell (build 時に render される static portion) + dynamic hole (request 時に render される dynamic portion) + Suspense boundary flush (dynamic hole の streaming flush event) + streaming assertion (shell と dynamic の境界 assertion) の 4 axis 統一実装。</p><h3 id="_7-interception-routes-interception-routes-ts" tabindex="-1">7. Interception routes (<code>interception-routes.ts</code>) <a class="header-anchor" href="#_7-interception-routes-interception-routes-ts" aria-label="Permalink to &quot;7. Interception routes (`interception-routes.ts`)&quot;">​</a></h3><p>(.) current-segment intercept + (..) parent-segment intercept + (...) root-catchall intercept + modal pattern (intercept で modal open、 直 URL 訪問で full page) の 4 axis 統一実装。</p><h3 id="_8-parallel-routes-advanced-parallel-routes-advanced-ts" tabindex="-1">8. Parallel routes advanced (<code>parallel-routes-advanced.ts</code>) <a class="header-anchor" href="#_8-parallel-routes-advanced-parallel-routes-advanced-ts" aria-label="Permalink to &quot;8. Parallel routes advanced (`parallel-routes-advanced.ts`)&quot;">​</a></h3><p>default.tsx slot (unmatched slot の fallback) + loading state slot (loading.tsx の parallel display) + error boundary (per-slot error boundary) + slot navigation (異なる slot への同時 navigation state machine) の 4 axis 統一実装。</p><h2 id="_3-dogfood-frontend-app-新規" tabindex="-1">3 dogfood frontend app 新規 <a class="header-anchor" href="#_3-dogfood-frontend-app-新規" aria-label="Permalink to &quot;3 dogfood frontend app 新規&quot;">​</a></h2><h3 id="dogfood-nextjs-rsc-streaming-app-v2-v1-34-2-issue-1049" tabindex="-1"><code>dogfood-nextjs-rsc-streaming-app</code> v2 (v1.34-2, Issue #1049) <a class="header-anchor" href="#dogfood-nextjs-rsc-streaming-app-v2-v1-34-2-issue-1049" aria-label="Permalink to &quot;`dogfood-nextjs-rsc-streaming-app` v2 (v1.34-2, Issue #1049)&quot;">​</a></h3><ul><li>Next.js 15.4 + React 19.1 + RSC + Suspense + streaming SSR + selective hydration + view transitions + form action advanced</li><li>testcontainers-shaped env-gate、 mock only + <code>KIWA_MODE=real NEXTJS_APP_ROUTER_BROWSER_READY=1</code> opt-in の 2 layer 走査</li><li>67 test (RSC harness + streaming SSR + view transitions + form action advanced の 4 axis 統一)</li></ul><h3 id="dogfood-nextjs-server-action-app-新規-v1-34-3-issue-1050" tabindex="-1"><code>dogfood-nextjs-server-action-app</code> (新規, v1.34-3, Issue #1050) <a class="header-anchor" href="#dogfood-nextjs-server-action-app-新規-v1-34-3-issue-1050" aria-label="Permalink to &quot;`dogfood-nextjs-server-action-app` (新規, v1.34-3, Issue #1050)&quot;">​</a></h3><ul><li>Next.js 15 form action + useFormStatus + useOptimistic + revalidatePath + revalidateTag + redirect + progressive enhancement</li><li>testcontainers-shaped env-gate、 form action + optimistic UI + revalidation の 3 axis を統一処理</li><li>70 test + Playwright e2e (form action progressive enhancement + optimistic UI reconciliation の E2E 保証)</li></ul><h3 id="dogfood-storybook-8-mdx-app-新規-v1-34-4-issue-1051" tabindex="-1"><code>dogfood-storybook-8-mdx-app</code> (新規, v1.34-4, Issue #1051) <a class="header-anchor" href="#dogfood-storybook-8-mdx-app-新規-v1-34-4-issue-1051" aria-label="Permalink to &quot;`dogfood-storybook-8-mdx-app` (新規, v1.34-4, Issue #1051)&quot;">​</a></h3><ul><li>Storybook 8 + MDX component preview + interaction test (@storybook/test) + coverage report</li><li>testcontainers-shaped env-gate、 CSF3 + MDX doc + interaction runner + coverage 4 axis の統一</li><li>71 test (Storybook 8 MDX + interaction runner + play function chain + coverage collection の 4 axis 統一)</li></ul><h2 id="縦深化-pair-pattern-第-6-pair-連続化" tabindex="-1">縦深化 pair pattern 第 6 pair 連続化 <a class="header-anchor" href="#縦深化-pair-pattern-第-6-pair-連続化" aria-label="Permalink to &quot;縦深化 pair pattern 第 6 pair 連続化&quot;">​</a></h2><p>v1.34 で kiwa の縦深化 pair pattern (basic mock milestone → 深化 II milestone で real driver + advanced semantics) が <strong>6 pair 連続完成</strong>:</p><ol><li><strong>Auth pair</strong> (v1.21 → v1.22) <ul><li>v1.21 = <code>@kiwa-lab/auth</code> v0.4 4 protocol adapter (WebAuthn L3 / Passkey / OAuth 2.1 / OIDC) mock only</li><li>v1.22 = Keycloak testcontainers + oauth2-mock-server + Chrome caBLE hybrid transport (real driver) + a11y axe-core gate</li></ul></li><li><strong>Realtime pair</strong> (v1.13 → v1.28) <ul><li>v1.13 = <code>@kiwa-lab/realtime</code> v0.1 4 provider (Supabase / Ably / Pusher / Socket.io) × 5 base semantics mock only</li><li>v1.28 = WebRTC + WebTransport + HTTP/3 + QUIC multiplexing + 8 axis advanced (real driver env-gate)</li></ul></li><li><strong>Streaming pair</strong> (v1.20 → v1.31) <ul><li>v1.20 = <code>@kiwa-lab/streaming</code> v0.1 3 provider (Kafka / Redpanda / NATS) × 5 semantics mock only</li><li>v1.31 = Kafka raw + Redpanda schema + NATS JetStream + 8 axis advanced (real driver env-gate + testcontainers)</li></ul></li><li><strong>Database pair</strong> (v1.14 → v1.32) <ul><li>v1.14-v1.26 = <code>@kiwa-lab/orm</code> v0.1-v0.9 3 ORM × 3 backend + 8 base semantics mock only</li><li>v1.32 = Postgres logical replication + MySQL cluster + SQLite WAL/FTS5 + 8 axis advanced (real driver env-gate + testcontainers)</li></ul></li><li><strong>Payment pair</strong> (v1.23 → v1.33) <ul><li>v1.14-v1.23 = <code>@kiwa-lab/payment</code> v0.2-v0.3 3 provider webhook + 9 base billing semantics mock only</li><li>v1.33 = Stripe Connect + Paddle Billing v2 + Lemon Squeezy license + 8 axis advanced billing II (real driver env-gate)</li></ul></li><li><strong>Frontend pair</strong> (v1.16 → v1.34、 this) <ul><li>v1.16 = <code>@kiwa-lab/component</code> v0.1-v0.2 3 target (Storybook 8 / Playwright CT / Chromatic) 6 base semantics mock only</li><li>v1.34 = <code>@kiwa-lab/component</code> v0.3 + <code>@kiwa-lab/nextjs</code> v1.2 8 axis advanced frontend semantics + real driver env-gate + Next.js 15 App Router + Storybook 8 MDX + Playwright CT + Chromatic</li></ul></li></ol><p>basic mock → advanced real driver の 2 phase pair を追加領域に横展開する pattern が SSOT 化された。 v1.25 perf + v1.27 mutation + v1.30 a11y の横串 triple pair と合わせて <strong>kiwa quality gate 縦横 grid maximum extension</strong>、 6 領域 (auth / realtime / streaming / database / payment / frontend) 完全 cover。</p><h2 id="v1-11-以降-24-milestone-連続完遂" tabindex="-1">v1.11 以降 24 milestone 連続完遂 <a class="header-anchor" href="#v1-11-以降-24-milestone-連続完遂" aria-label="Permalink to &quot;v1.11 以降 24 milestone 連続完遂&quot;">​</a></h2><p>v1.11 (release gate) → v1.12 (非決定性) → v1.13 (時間軸) → v1.14 (横軸拡張) → v1.15 (AI-LLM 深化) → v1.16 (component 縦軸) → v1.17 (Observability v2) → v1.18 (Blockchain 深化) → v1.19 (Framework 深化) → v1.20 (Streaming 深化) → v1.21 (Auth 深化) → v1.22 (Auth 深化 II) → v1.23 (Payment 深化) → v1.24 (Edge / Serverless 深化) → v1.25 (Perf-harness sweep) → v1.26 (Database 深化) → v1.27 (Mutation testing sweep) → v1.28 (Realtime 深化 II) → v1.29 (release script filter SSOT) → v1.30 (a11y 横串 sweep) → v1.31 (Streaming 深化 II) → v1.32 (Database 深化 II) → v1.33 (Payment 深化 II) → <strong>v1.34 (Frontend 深化)</strong>。</p><h2 id="_12-milestone-連続-snippet-validation-streak" tabindex="-1">12 milestone 連続 snippet validation streak <a class="header-anchor" href="#_12-milestone-連続-snippet-validation-streak" aria-label="Permalink to &quot;12 milestone 連続 snippet validation streak&quot;">​</a></h2><p>v1.23 (payment 深化) から v1.34 (frontend 深化) まで <strong>12 milestone 連続で snippet validation pattern</strong> を land 済:</p><p>payment-v1.23 / edge-v1.24 / perf-harness-v1.25 / orm-v1.26 / quality-metrics-v1.27 / realtime-v1.28 / release-invariants-v1.29 / a11y-v1.30 / streaming-v1.31 / orm-v1.32 / payment-v1.33 / <strong>frontend-v1.34</strong>。</p><p>各 milestone の tutorial code snippet はすべて <code>docs-tutorial-v1.XX.test.ts</code> で自動検証されている (<code>packages/component/tests/docs-tutorial-v1.34.test.ts</code> は 12 milestone 目の追加)。</p><h2 id="try-it" tabindex="-1">Try it <a class="header-anchor" href="#try-it" aria-label="Permalink to &quot;Try it&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -D</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @kiwa-lab/component</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @kiwa-lab/nextjs</span></span></code></pre></div><p>Migration guide (additive-only、 breaking change なし):</p><ul><li><a href="https://cardene777.github.io/kiwa/migrations/v1.33-to-v1.34" target="_blank" rel="noreferrer">v1.33 → v1.34 migration guide</a></li><li><a href="https://cardene777.github.io/kiwa/concepts/frontend-real-driver-testing" target="_blank" rel="noreferrer">Frontend real-driver testing SSOT concept doc</a></li></ul><h2 id="v2-0-で解決したい問題" tabindex="-1">v2.0 で解決したい問題 <a class="header-anchor" href="#v2-0-で解決したい問題" aria-label="Permalink to &quot;v2.0 で解決したい問題&quot;">​</a></h2><ul><li>Multi-version Vitest matrix — Vitest 1.x vs 2.x vs 3.x parity check</li><li>Desktop (Electron / Tauri) + mobile (React Native / Expo) adapter</li><li>Coverage 100 % milestone</li><li>Cache depth II — Dragonfly + KeyDB failover + Redis cluster resharding + eviction ML</li><li>Queue depth II — BullMQ Pro + Inngest Fn v2 + AWS SQS FIFO + RabbitMQ federation</li><li>AI-LLM depth II — Anthropic Messages Batch API + OpenAI Realtime API + Vercel AI SDK v4 + LangGraph fan-out</li><li>L2 depth — Base / Arbitrum / Optimism / Scroll block-space fidelity</li><li>ZK depth — Noir / Circom / RISC Zero test harness</li><li>IoT depth — MQTT / CoAP / LWM2M</li><li>DB depth III — SurrealDB / EdgeDB / Turso / CockroachDB / TimescaleDB / QuestDB</li><li>Streaming depth III — Pulsar + KsqlDB + Faust + Flink + Beam pipeline fidelity</li><li>Auth depth III — WebAuthn L3 + Passkey caBLE + Federation + Verifiable Credentials</li><li>Perf-harness sweep II — real-machine baseline、 macOS ARM64 + Linux x86_64 + Windows x86_64</li></ul><p>これらのうちどれを v2.0 に land すべきかの feedback を GitHub Discussions で募集中。</p><h2 id="thanks" tabindex="-1">Thanks <a class="header-anchor" href="#thanks" aria-label="Permalink to &quot;Thanks&quot;">​</a></h2><p>v1.34 sub-Issue を review していただいた方、 <code>@kiwa-lab/component</code> v0.3 + <code>@kiwa-lab/nextjs</code> v1.2 pre-release を試していただいた方、 縦深化 pair pattern SSOT を 6-pair grid に整理する議論に付き合っていただいた方、 ありがとうございます。 v2.0 へ。</p>',50)])])}const h=a(n,[["render",o]]);export{m as __pageData,h as default};
